DO $$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.crm_import_history_batch(text,text,jsonb,jsonb)'::regprocedure) INTO body; body:=replace(body,'n integer:=0;','n integer:=0; affected integer:=0;'); body:=replace(body,'WHERE key<>''id''','WHERE key IS NOT NULL'); body:=replace(body,'IF FOUND THEN n:=n+1;CONTINUE; END IF;','GET DIAGNOSTICS affected=ROW_COUNT; IF affected>0 THEN n:=n+1;CONTINUE; END IF;'); body:=replace(body,'IF NOT FOUND THEN RAISE EXCEPTION','GET DIAGNOSTICS affected=ROW_COUNT; IF affected=0 THEN RAISE EXCEPTION'); EXECUTE body; END $$;